//! Rename whole registered folders. Their unrelated contents stay in place.
use std::{fs,path::{Path,PathBuf}};
use serde_json::{Value,json};
use crate::studio_files as disk;
fn safe(root:&Path,rel:&str)->Result<PathBuf,String>{let path=root.join(disk::relative(rel)?);let mut parent=path.clone();while !parent.exists(){parent.pop();}if !parent.canonicalize().map_err(|e|e.to_string())?.starts_with(root){return Err("Folder points outside the project".into())}if fs::symlink_metadata(&path).map(|m|m.file_type().is_symlink()).unwrap_or(false){return Err("Choose a real project folder, not a symbolic link".into())}Ok(path)}
fn replace(value:&str,moves:&[Value],root:&str)->String{for m in moves{let from=m["from"].as_str().unwrap();let to=m["to"].as_str().unwrap();for(prefix,target)in [(from.to_owned(),to.to_owned()),(format!("{root}/{from}"),format!("{root}/{to}"))]{if value==prefix{return target}if let Some(rest)=value.strip_prefix(&(prefix+"/")){return target+"/"+rest}}}value.into()}
fn rebase(v:&mut Value,moves:&[Value],root:&str,key:&str){match v{Value::Object(map)=>{let old=std::mem::take(map);for(k,mut value)in old{rebase(&mut value,moves,root,if key=="chapterDirectories"{key}else{&k});let next=if ["files","previews","fileStates","chapterDirectoryStates"].contains(&key){replace(&k,moves,root)}else{k};map.insert(next,value);}},Value::Array(items)=>for item in items{rebase(item,moves,root,key)},Value::String(s)if key=="chapterDirectories"||["path","relativePath","directory","folderPath","audioPath","previewPath","vaultRelativePath","sourcePath","audioRelativePath","cleanupChapterDirectories"].contains(&key)=>*s=replace(&s.replace('\\',"/"),moves,root),_=>{}}}
pub fn recover(root:&Path)->Result<(),String>{let link=root.join("Studio Link");let file=link.join("folder-rename-journal.json");if !file.exists(){return Ok(())}let journal:Value=serde_json::from_slice(&fs::read(&file).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;let rows=journal["moves"].as_array().ok_or("Invalid folder recovery journal")?;
 if journal["phase"]=="committed"{fs::remove_file(file).map_err(|e|e.to_string())?;return Ok(())}
 for m in rows{let stage=safe(root,m["stage"].as_str().ok_or("Missing stage")?)?;let to=safe(root,m["to"].as_str().ok_or("Missing destination")?)?;if journal["phase"]=="installing"&&!stage.exists()&&to.exists(){fs::rename(to,stage).map_err(|e|e.to_string())?;}}
 for m in rows{let stage=safe(root,m["stage"].as_str().unwrap())?;if stage.exists(){let from=safe(root,m["from"].as_str().unwrap())?;if from.exists(){return Err("Folder recovery destination is occupied; no files were overwritten".into())}fs::rename(stage,from).map_err(|e|e.to_string())?;}}
 for(name,text)in journal["documents"].as_object().ok_or("Missing original shared records")?{disk::atomic_json(&link,name,text.as_str().ok_or("Invalid shared record recovery")?)?;}
 fs::remove_file(file).map_err(|e|e.to_string())?;Ok(())}
pub fn rename(directory:String,project_id:String,moves:Vec<Value>,naming:Option<Value>)->Result<Value,String>{let root=disk::root(&directory)?;let _lock=crate::media_organization::lock(&root)?;recover(&root)?;let link=root.join("Studio Link");let manifest:Value=serde_json::from_slice(&fs::read(link.join("project.json")).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;if manifest["project"]["id"]!=project_id{return Err("This folder belongs to another project".into())}
 let stage_id=std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_nanos();let mut actual=Vec::new();let mut sources=std::collections::HashSet::new();let mut targets=std::collections::HashSet::new();
 for m in moves{let from=m["from"].as_str().ok_or("Missing original folder")?;let to=m["to"].as_str().ok_or("Missing new folder")?;if from==to{continue}let a=safe(&root,from)?;let b=safe(&root,to)?;if from.starts_with("Studio Link")||to.starts_with("Studio Link")||a.parent()!=b.parent(){return Err("Only registered chapter/archive folder names can change here".into())}if !a.exists(){continue}if !a.is_dir(){return Err("The original folder is not a directory".into())}if !sources.insert(from.to_lowercase())||!targets.insert(to.to_lowercase()){return Err("The folder pattern gives two chapters the same folder".into())}actual.push(json!({"from":from,"to":to,"stage":format!("Studio Link/.folder-stage-{stage_id}-{}",actual.len())}));}
 for m in &actual{let to=m["to"].as_str().unwrap();if safe(&root,to)?.exists()&&!sources.contains(&to.to_lowercase()){return Err(format!("Cannot rename folder to {to}: that folder already exists. Nothing was changed."))}}
 let mut documents=serde_json::Map::new();for e in fs::read_dir(&link).map_err(|e|e.to_string())?{let p=e.map_err(|e|e.to_string())?.path();if p.extension().and_then(|x|x.to_str())==Some("json")&&p.file_name().and_then(|x|x.to_str())!=Some("folder-rename-journal.json"){let text=fs::read_to_string(&p).map_err(|e|e.to_string())?;serde_json::from_str::<Value>(&text).map_err(|_|format!("Unreadable shared record: {}",p.display()))?;documents.insert(p.file_name().unwrap().to_string_lossy().into_owned(),json!(text));}}
 if actual.is_empty(){return Ok(json!({"moves":[]}))}let revision=std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_nanos().to_string();let mut journal=json!({"phase":"staging","moves":actual,"documents":documents});disk::atomic_json(&link,"folder-rename-journal.json",&journal.to_string())?;
 let result=(||{for m in &actual{fs::rename(safe(&root,m["from"].as_str().unwrap())?,safe(&root,m["stage"].as_str().unwrap())?).map_err(|e|e.to_string())?;}journal["phase"]=json!("installing");disk::atomic_json(&link,"folder-rename-journal.json",&journal.to_string())?;for m in &actual{fs::rename(safe(&root,m["stage"].as_str().unwrap())?,safe(&root,m["to"].as_str().unwrap())?).map_err(|e|e.to_string())?;}
 let root_name=root.to_string_lossy().replace('\\',"/");for(name,text)in &documents{let mut value:Value=serde_json::from_str(text.as_str().unwrap()).map_err(|e|e.to_string())?;rebase(&mut value,&actual,&root_name,"");if name=="project.json"{if let Some(profile)=&naming{value["naming"]=profile.clone();value["namingRevision"]=json!(revision);}}disk::atomic_json(&link,name,&value.to_string())?;}journal["phase"]=json!("committed");disk::atomic_json(&link,"folder-rename-journal.json",&journal.to_string())?;Ok::<(),String>(())})();if let Err(e)=result{recover(&root).map_err(|r|format!("{e}; recovery requires attention: {r}"))?;return Err(e)}fs::remove_file(link.join("folder-rename-journal.json")).map_err(|e|e.to_string())?;Ok(json!({"moves":actual,"namingRevision":revision}))}
#[tauri::command]pub async fn rename_project_folders(directory:String,project_id:String,moves:Vec<Value>,naming:Option<Value>)->Result<Value,String>{tauri::async_runtime::spawn_blocking(move||rename(directory,project_id,moves,naming)).await.map_err(|e|e.to_string())?}
#[cfg(test)]mod tests{use super::*;
 fn setup()->PathBuf{let root=std::env::temp_dir().join(format!("folder-rename-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));fs::create_dir_all(root.join("Studio Link")).unwrap();fs::write(root.join("Studio Link/project.json"),json!({"project":{"id":"p"},"storyboards":{"one":{"relativePath":"Old/1.png"}},"note":"Old/1.png"}).to_string()).unwrap();fs::create_dir(root.join("Old")).unwrap();fs::write(root.join("Old/1.png"),b"drawing").unwrap();fs::write(root.join("Old/random.jpg"),b"unrelated").unwrap();root.canonicalize().unwrap()}
 #[test]fn rename_keeps_unregistered_contents_and_updates_only_paths(){let r=setup();rename(r.to_string_lossy().into(),"p".into(),vec![json!({"from":"Old","to":"New"})],None).unwrap();assert!(!r.join("Old").exists());assert_eq!(fs::read(r.join("New/random.jpg")).unwrap(),b"unrelated");let p:Value=serde_json::from_slice(&fs::read(r.join("Studio Link/project.json")).unwrap()).unwrap();assert_eq!(p["storyboards"]["one"]["relativePath"],"New/1.png");assert_eq!(p["note"],"Old/1.png");fs::remove_dir_all(r).unwrap();}
 #[test]fn collision_changes_nothing(){let r=setup();fs::create_dir(r.join("New")).unwrap();assert!(rename(r.to_string_lossy().into(),"p".into(),vec![json!({"from":"Old","to":"New"})],None).is_err());assert!(r.join("Old/1.png").exists());assert!(fs::read_dir(r.join("New")).unwrap().next().is_none());fs::remove_dir_all(r).unwrap();}
}
#[cfg(test)]mod recovery_tests{use super::*;
 #[test]fn interrupted_whole_folder_install_restores_original_layout_and_records(){let r=std::env::temp_dir().join(format!("folder-crash-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));fs::create_dir_all(r.join("Studio Link")).unwrap();fs::create_dir(r.join("New")).unwrap();fs::write(r.join("New/random.png"),b"keep").unwrap();let before=json!({"project":{"id":"p"},"path":"Old/random.png"}).to_string();fs::write(r.join("Studio Link/project.json"),b"{}").unwrap();let journal=json!({"phase":"installing","moves":[{"from":"Old","to":"New","stage":"Studio Link/.folder-stage"}],"documents":{"project.json":before}});fs::write(r.join("Studio Link/folder-rename-journal.json"),journal.to_string()).unwrap();recover(&r).unwrap();assert_eq!(fs::read(r.join("Old/random.png")).unwrap(),b"keep");assert!(!r.join("New").exists());assert_eq!(fs::read_to_string(r.join("Studio Link/project.json")).unwrap(),before);fs::remove_dir_all(r).unwrap();}
}
